'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var increwvariance = require( '@stdlib/stats/incr/ewvariance' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes an exponentially weighted variance, ignoring `NaN` values.
*
* @param {NonNegativeNumber} alpha - smoothing factor
* @throws {TypeError} must provide a nonnegative number
* @throws {RangeError} must be on the interval `[0,1]`
* @returns {Function} accumulator function
*
* @example
* var incrnanewvariance = require( '@stdlib/stats/incr/nanewvariance' );
*
* var accumulator = incrnanewvariance( 0.5 );
*
* var v = accumulator();
* // returns null
*
* v = accumulator( 2.0 );
* // returns 0
*
* v = accumulator( 4.0 );
* // returns 1.0
*
* v = accumulator( NaN );
* // returns 1.0
*
* v = accumulator( 5.0 );
* // returns 1.5
*
* v = accumulator();
* // returns 1.5
*/
function nanewvariance( alpha ) {
	var acc = increwvariance( alpha );
	return accumulator;

	/**
	* Updates and returns the exponentially weighted variance when provided a numeric input.
	* If no input is provided, returns the current exponentially weighted variance.
	*
	* @private
	* @param {number} [x] - new value
	* @returns {(number|null)} updated exponentially weighted variance or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 || isnan( x ) ) {
			return acc();
		}
		return acc( x );
	}
}


// EXPORTS //

module.exports = nanewvariance;
